struct Row {
    left: String
    right: String
}
fn fail(label: str) -> String ! String { return err(label.toString()) }
fn failInt() -> int ! String { return err("call".toString()) }
fn accept(first: String, second: int) -> int { return first.len() + second }
fn vector() -> Vec[String] ! String {
    return [format("first:${1}"), try fail("vec")]
}
fn object() -> Row ! String {
    return Row{left: format("left:${2}"), right: try fail("struct")}
}
fn argument() -> int ! String {
    return accept(format("arg:${3}"), try failInt())
}
fn checkVector() {
    let _ = vector() catch error {
        println(error)
        return
    }
}
fn checkObject() {
    let _ = object() catch error {
        println(error)
        return
    }
}
fn checkArgument() {
    let _ = argument() catch error {
        println(error)
        return
    }
}
fn main() {
    checkVector()
    checkObject()
    checkArgument()
}

fn choose(value: int) -> int ! String {
    if value == 1 { return value }
    return err("discarded".toString())
}
fn main() {
    var seen = 0
    for value in 0..3 {
        seen += 1
        println("row:${format("hold")}:${choose(value) catch error { continue }}")
    }
    println(seen)
    seen = 0
    for value in 1..4 {
        seen += 1
        println("break:${format("hold")}:${choose(value) catch error { break }}")
    }
    println(seen)
}
